export class Reservation {
  private minutes = 30;
  changeDuration(minutes: number) {
    if (minutes > 90) throw new Error("Reservation exceeds 90 minutes");
    this.minutes = minutes;
  }
}

Passages.http-change.ts:
export function changeDurationHttp(reservation: Reservation, body: { minutes: number }) {
  if (body.minutes > 90) return { status: 400, error: "Too long" };
  reservation.changeDuration(body.minutes);
  return { status: 200 };
}

